WFJ.Data.add("spell", {
  [429125] = { "Accelera il lancio d'incantesimi, aumentando la velocità di lancio del $N1% e riducendo del $N2% il ritardo subito dagli attacchi dannosi durante il lancio. Dura $D1.", nil, 0xa582f7cd, nil, "um" },
  [429147] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [429242] = { "Incidi sui tuoi bracciali la runa Grazia della Luce:\n\n$I1\nIl tuo incantesimo Luce Sacra riduce di $D1 il tempo di lancio del tuo prossimo incantesimo Luce Sacra. Dura $D2.", nil, 0xc71d8de2, nil, "um" },
  [429247] = { "Incidi sul tuo elmo la runa Improved Sanctuary:\n\n$I1\nAumenta del $N1% i danni prevenuti dalla tua Blessing of Sanctuary e aumenta i danni inflitti dalla tua Blessing of Sanctuary del $N2% del tuo indice di blocco con lo scudo.", nil, 0x58782ca0, nil, "um" },
  [429249] = { "Incidi sul tuo elmo la runa Wrath:\n\n$I1\nI danni della tua Consacrazione ora possono essere critici, e i danni dei tuoi incantesimi Esorcismo, Folgore Sacra, Luce Solare, Ira Sacra e Consacrazione ottengono una probabilità di critico aggiuntiva pari alla tua probabilità di critico in mischia.", nil, 0x561fc040, nil, "um" },
  [429251] = { "Incidi sul tuo elmo la runa Fanatismo:\n\n$I1\nAumenta del $N1% la tua probabilità di critico con gli incantesimi. Inoltre, i tuoi incantesimi di cura critici curano il bersaglio del $N2% della quantità curata in $D1.", nil, 0x3e638f20, nil, "um" },
  [429255] = { "Incidi sui tuoi bracciali la runa Purifying Power:\n\n$I1\nRiduce del $N1% il costo in mana dei tuoi incantesimi Purificazione e Depurazione e riduce del $N2% il tempo di recupero dei tuoi incantesimi Esorcismo e Ira Sacra.", nil, 0x90f0bff6, nil, "um" },
  [429261] = { "Incidi sui tuoi bracciali la runa ⟦Hammer of Wrath=Martello dell'Ira⟧:\n\n$I1\n⟦Hammer of Wrath=Martello dell'Ira⟧ ora è istantaneo e il suo tempo di recupero si azzera ogni volta che danneggia un nemico con meno del $N1% di salute.", nil, 0xd1838ce5, nil, "um" },
  [429304] = { "Incidi sul tuo elmo la runa Gelo Profondo:\n\n$I1\nStordisce il bersaglio per $D1. Utilizzabile solo su bersagli congelati. Infligge $N2 danni ai bersagli immuni in modo permanente allo stordimento. Questi danni beneficiano delle applicazioni di Glaciazione, senza consumarle.", nil, 0xee3fd969, nil, "um" },
  [429306] = { "Incidi sul tuo elmo la runa Anomalia Temporale:\n\n$I1\nLancia un globo di energia temporale che avanza lentamente e ogni $D1 fornisce a tutti i membri del gruppo vicini uno scudo che assorbe $N2 danni per $D2. Lo scudo accumula valore aggiuntivo se i membri del gruppo restano vicino al globo.", nil, 0x463a9f72, nil, "um" },
  [429308] = { "Incidi sui tuoi bracciali la runa Armatura Lavica:\n\n$I1\nInfligge $N1 danni da fuoco quando vieni colpito, aumenta del $N2% la tua probabilità di critico con gli incantesimi e riduce del $N3% la probabilità di subire colpi critici. Sul Mago può essere attivo un solo tipo di incantesimo di armatura alla volta. Dura $D1.", nil, 0x4406c7f1, nil, "um" },
  [429309] = { "Incidi sui tuoi bracciali la runa Dislocazione:\n\n$I1\nTi teletrasporta nel punto in cui hai lanciato Traslazione l'ultima volta e azzera il tempo di recupero di Traslazione. Utilizzabile solo entro $D1 dal lancio di Traslazione.", nil, 0x19928642, nil, "um" },
  [429311] = { "Incidi sui tuoi bracciali la runa Balefire Bolt:\n\n$I1\nScatena contro il nemico un'esplosione di magia pura che distorce la realtà, infliggendo $N1 danni chimerici.\n\nAumenta del $N2% i danni di Balefire Bolt e Pirosfera e riduce del $N3% il tuo Spirito, effetto cumulabile fino a $N4 volte per $D1. Se il tuo Spirito scende a $N6, muori.\n\nQuesto incantesimo viene confrontato con la più bassa tra le resistenze del bersaglio all'arcano, al fuoco e al gelo.", nil, 0x3f054c1a, nil, "um" },
  [429432] = { nil, "Gli alleati entro $N1 m dalla Priestess of the Moon ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0x270bb4b9, "mu" },
  [429434] = { "Lancia un dardo di magia oscura contro un bersaglio nemico, infliggendo danni da ombra.", nil, 0x42ce8448, nil, "um" },
  [429436] = { nil, "Gli alleati entro $N1 m dalla Priestess of the Moon ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0x270bb4b9, "mu" },
  [429541] = { nil, "Tutti i danni subiti ridotti del $N1%.", nil, 0xbd0656aa, "mu" },
  [429543] = { nil, "La magia che vincola l'elementale si sta sciogliendo e irradia mana grezzo sui giocatori vicini.", nil, 0xd7aae66f, "mu" },
  [429578] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [429687] = { "Prende il controllo di un nemico umanoide fino al livello $N1 per $D1.", "Ammaliato.", 0x54466006, 0xd83f67a3, "uu" },
  [429688] = { "Prende il controllo di un nemico umanoide fino al livello $N1 per $D1, ma aumenta l'intervallo tra i suoi attacchi del $N3%.", "Ammaliato.\nIntervallo tra gli attacchi aumentato del $N1%.", 0xa2a4015c, 0xd198bff7, "uu" },
  [429821] = { "Scaglia una freccia infuocata contro un nemico, infliggendo i danni dell'arma e $N1 danni aggiuntivi. Tutti i danni inflitti sono danni da fuoco.", nil, 0xc91c8900, nil, "um" },
  [429823] = { "Infligge $N1 danni da arcano a un nemico, poi altri $N2 danni ogni $D1 per $D2.", "$N1 danni da arcano inflitti ogni $D1.", 0x59824b40, 0xd8708d96, "uu" },
  [429825] = { "Colpisce un nemico con un dardo elettrico che danneggia anche altri bersagli vicini. L'incantesimo colpisce fino a un massimo di $N1 bersagli, infliggendo danni da natura maggiori a ogni bersaglio successivo.", nil, 0x245b0721, nil, "um" },
